import json
import math
from collections import Counter, defaultdict

STATE_PATH = "/tmp/opencode/state.json"

def load_state():
    with open(STATE_PATH, "r") as f:
        return json.load(f)

def save_state(st):
    with open(STATE_PATH, "w") as f:
        json.dump(st, f, indent=2, sort_keys=True)

def compute_posteriors(st, lam_ah_inn=0.1316):
    emps = [e["id"] for e in st["employees"]]
    emp_info = {e["id"]: e for e in st["employees"]}
    decoy = st.get("decoy")
    docs = st["documents"] # doc_id -> {day, recipients, is_canary, assignment}

    alive = {e: (e != decoy) for e in emps}
    log_ll = {e: 0.0 for e in emps}

    # 1. Surfaced leaks (100% DSL-invariant!)
    for lk in st["leaks"]:
        doc_id = lk["doc_id"]
        var_shown = lk.get("variant")
        doc = docs[doc_id]
        rec_set = set(doc["recipients"])
        for e in emps:
            if e not in rec_set:
                alive[e] = False
            elif alive[e] and doc["is_canary"] and var_shown is not None:
                asgn = doc["assignment"]
                distinct_vars = set(asgn.values())
                nv = len(distinct_vars)
                if nv > 1:
                    if asgn[e] == var_shown:
                        log_ll[e] += math.log(0.95)
                    else:
                        log_ll[e] += math.log(0.05 / (nv - 1))

    # 2. Access logs per closed day
    closed_days = set(st["closed_log_days"])
    n_days = len(closed_days)
    reg_cnt = Counter()
    ah_cnt = Counter()
    for lg in st["logs"]:
        if lg["day"] in closed_days:
            if lg["after_hours"]:
                ah_cnt[lg["employee"]] += 1
            else:
                reg_cnt[lg["employee"]] += 1

    if n_days > 0:
        for e in emps:
            if not alive[e]:
                continue
            r = reg_cnt[e]
            a = ah_cnt[e]
            # Mole: reg ~ Pois(0.7 * n_days), ah ~ Pois(0.3 * n_days)
            # Innocent (non-decoy): reg ~ Pois(0.9 * n_days), ah ~ Pois(lam_ah_inn * n_days)
            ll_m = -0.7 * n_days + r * math.log(0.7) - 0.3 * n_days + a * math.log(0.3)
            ll_i = -0.9 * n_days + r * math.log(0.9) - lam_ah_inn * n_days + a * math.log(lam_ah_inn)
            log_ll[e] += (ll_m - ll_i)

    # 3. Interviews (deduplicated by (day, employee, topic))
    seen_int = set()
    for iv in st["interviews"]:
        key = (iv["day"], iv["employee"], iv["topic"])
        if key in seen_int:
            continue
        seen_int.add(key)
        e = iv["employee"]
        if not alive.get(e, False):
            continue
        if iv["evasive"]:
            log_ll[e] += math.log(0.24 / 0.20)
        else:
            log_ll[e] += math.log(0.76 / 0.80)

    cand = [e for e in emps if alive[e]]
    mx = max(log_ll[e] for e in cand)
    probs = {e: math.exp(log_ll[e] - mx) for e in cand}
    Z = sum(probs.values())
    probs = {e: probs[e] / Z for e in cand}

    ranked = sorted(cand, key=lambda e: -probs[e])
    return ranked, probs, alive, reg_cnt, ah_cnt

def print_summary():
    st = load_state()
    ranked, probs, alive, reg_cnt, ah_cnt = compute_posteriors(st)
    emp_info = {e["id"]: e for e in st["employees"]}
    print(f"=== Day {st['current_day']} | Alive suspects: {len(ranked)} | Closed log days: {len(st['closed_log_days'])} | Leaks: {len(st['leaks'])} ===")
    if st.get("decoy"):
        d = st["decoy"]
        print(f"Decoy: {d} ({emp_info[d]['dept']} c{emp_info[d]['clearance']}) reg={reg_cnt[d]} ah={ah_cnt[d]}")
    for idx, e in enumerate(ranked[:15]):
        inf = emp_info[e]
        iv_e = [iv for iv in st["interviews"] if iv["employee"] == e]
        ev_s = f"{sum(x['evasive'] for x in iv_e)}/{len(iv_e)}"
        print(f"{idx+1:2d}. {e} ({inf['dept']:11s} c{inf['clearance']}) P={probs[e]:.4f} | reg={reg_cnt[e]:2d} ah={ah_cnt[e]:2d} | ev={ev_s}")

if __name__ == "__main__":
    print_summary()

